import std/io (readFile, writeFile, println)
import std/json (decode, Json, JNull, JObject, JString, JNumber, JArray)
import std/string (length, substring, _str_eq)

type Config = {
  app_name: string,
  version: string,
  port: int,
  features: List[string]
}

-- Helper to validate port range
func validatePort(port: int) -> bool {
  port >= 1024 && port <= 65535
}

-- Helper to count occurrences of a character (string) in a string
func countChar(s: string, char: string) -> int {
  let s_len = length(s) in
  let rec loop = \idx. \count.
    if idx >= s_len
    then count
    else if _str_eq(substring(s, idx, 1), char)
    then loop(idx + 1)(count + 1)
    else loop(idx + 1)(count)
  in
  loop(0)(0)
}

-- Helper to validate version format (simple check: contains two dots)
func validateVersion(ver: string) -> bool {
  countChar(ver, ".") == 2
}

-- Helper to find a key in a JSON object's list of key-value pairs
func findKey(kvs: List[{key: string, value: Json}], target: string) -> Json {
  match kvs {
    [] => JNull,
    ::(kv, rest) => if _str_eq(kv.key, target) then kv.value else findKey(rest, target)
  }
}

-- Helper to extract a field from a Json object
func getField(json: Json, field: string) -> Json {
  match json {
    JObject(kvs) => findKey(kvs, field),
    _ => JNull -- Not an object, or not found in object, return JNull
  }
}

-- Helper to convert JArray of JString to List[string]
func jsonArrayToStringList(json_array: List[Json]) -> List[string] {
  match json_array {
    [] => [],
    ::(elem, rest) => match elem {
      JString(s) => s :: jsonArrayToStringList(rest),
      _ => jsonArrayToStringList(rest) -- Skip non-string elements
    }
  }
}

-- Default config in case of severe parsing or validation failure
let defaultInvalidConfig: Config = {
  app_name: "InvalidApp",
  version: "0.0.0",
  port: 0,
  features: []
}

-- Recursive list length (assuming generic length for List[a] is not in std/string)
export func listLength[a](xs: List[a]) -> int {
  match xs {
    [] => 0,
    ::(_, rest) => 1 + listLength(rest)
  }
}

-- Load config from file, parse JSON, validate, and return Config record
export func loadConfig(filename: string) -> Config ! {FS, IO} {
  let content = readFile(filename); -- readFile returns string

  match decode(content) {
    Ok(json_doc) => {
      let app_name_json = getField(json_doc, "app_name") in
      let version_json = getField(json_doc, "version") in
      let port_json = getField(json_doc, "port") in
      let features_json = getField(json_doc, "features") in

      let app_name = match app_name_json { JString(s) => s, _ => "UnknownApp" } in
      let version = match version_json { JString(s) => s, _ => "0.0.0" } in
      let port = match port_json { JNumber(f) => floatToInt(f), _ => 0 } in
      let features_list = match features_json { JArray(arr) => jsonArrayToStringList(arr), _ => [] } in

      -- Perform validations
      let port_valid = validatePort(port) in
      let version_valid = validateVersion(version) in
      let features_not_empty = listLength(features_list) > 0 in

      if port_valid && version_valid && features_not_empty
      then {
        app_name: app_name,
        version: version,
        port: port,
        features: features_list
      }
      else {
        -- Log validation errors
        if not port_valid then println("Validation Error: Port " ++ show(port) ++ " is out of range.");
        if not version_valid then println("Validation Error: Invalid version format: " ++ version ++ ".");
        if not features_not_empty then println("Validation Error: Features list cannot be empty.");
        defaultInvalidConfig
      }
    },
    Err(msg) => {
      println("JSON parsing error: " ++ msg);
      defaultInvalidConfig
    }
  }
}

export func main() -> () ! {IO, FS} {
  -- Create config file
  let configJson = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  let _ = writeFile("app_config.json", configJson);

  -- Load and validate config
  let config = loadConfig("app_config.json");

  -- Print result
  let numFeatures = listLength(config.features);
  println("Loaded " ++ config.app_name ++ " v" ++ config.version ++ " on port " ++ show(config.port) ++ " with " ++ show(numFeatures) ++ " features")
}

