import json
from pathlib import Path
from typing import List, TypedDict

class Config(TypedDict):
    app_name: str
    version: str
    port: int
    features: List[str]

def _validate_port(port: int) -> bool:
    """Helper to validate port range."""
    return 1024 <= port <= 65535

def _validate_version(version: str) -> bool:
    """Helper to validate version format (contains two dots)."""
    return version.count(".") == 2

def load_config(filename: Path) -> Config:
    """
    Loads and validates a configuration from a JSON file.

    Args:
        filename: The path to the configuration file.

    Returns:
        A Config TypedDict containing the validated configuration.

    Raises:
        FileNotFoundError: If the configuration file does not exist.
        ValueError: If the JSON is malformed, essential fields are missing,
                    or validation rules are violated.
    """
    try:
        with open(filename, "r", encoding="utf-8") as f:
            raw_config = json.load(f)
    except FileNotFoundError:
        raise FileNotFoundError(f"Configuration file not found: {filename}")
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON format in {filename}: {e}")
    except Exception as e:
        raise ValueError(f"An unexpected error occurred reading {filename}: {e}")

    if not isinstance(raw_config, dict):
        raise ValueError(f"Invalid config structure: expected a dictionary at root, got {type(raw_config).__name__}")

    try:
        app_name = raw_config["app_name"]
        version = raw_config["version"]
        port = raw_config["port"]
        features = raw_config["features"]
    except KeyError as e:
        raise ValueError(f"Missing expected field in config: {e}")

    # Type and value validation
    if not isinstance(app_name, str):
        raise ValueError("Config field 'app_name' must be a string.")
    if not isinstance(version, str):
        raise ValueError("Config field 'version' must be a string.")
    if not isinstance(port, int):
        raise ValueError("Config field 'port' must be an integer.")
    if not isinstance(features, list):
        raise ValueError("Config field 'features' must be a list.")
    if not all(isinstance(f, str) for f in features):
        raise ValueError("All elements in 'features' list must be strings.")

    if not _validate_port(port):
        raise ValueError(f"Port {port} is out of valid range (1024-65535).")
    if not _validate_version(version):
        raise ValueError(f"Version '{version}' does not match X.Y.Z format (e.g., 1.0.0).")
    if not features:
        raise ValueError("Features list cannot be empty.")

    return Config(app_name=app_name, version=version, port=port, features=features)

def main() -> None:
    """
    Main function to create a config file, load it, validate, and print results.
    """
    config_filename = Path("app_config.json")

    # Task Step 1: Create JSON config file
    config_data = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "port": 8080,
        "features": ["logging", "auth", "api"]
    }
    try:
        with open(config_filename, "w", encoding="utf-8") as f:
            json.dump(config_data, f, indent=2)
    except IOError as e:
        print(f"Error creating config file '{config_filename}': {e}")
        return

    # Task Step 4: Call loadConfig and print result
    try:
        config = load_config(config_filename)
        num_features = len(config["features"])
        print(f"Loaded {config['app_name']} v{config['version']} on port {config['port']} with {num_features} features")
    except (FileNotFoundError, ValueError) as e:
        print(f"Error loading configuration: {e}")

if __name__ == "__main__":
    main()

