from typing import TypeVar, Generic, Callable

T = TypeVar('T')

class Pure(Generic[T]):
    """Wrapper for pure values - prevents calling effectful functions"""
    def __init__(self, value: T):
        self._value = value

    def get(self) -> T:
        return self._value

class IO(Generic[T]):
    """Wrapper for effectful computations - can call pure functions"""
    def __init__(self, action: Callable[[], T]):
        self._action = action

    def run(self) -> T:
        return self._action()

def double(x: int) -> Pure[int]:
    """PURE: Returns x * 2 with no side effects"""
    return Pure(x * 2)

def add(a: int, b: int) -> Pure[int]:
    """PURE: Returns a + b with no side effects"""
    return Pure(a + b)

def printResult(label: str, value: int) -> IO[None]:
    """EFFECTFUL: Prints label and value (has IO side effect)"""
    def action():
        print(f"{label}: {value}")
    return IO(action)

def compute_and_print() -> IO[None]:
    """EFFECTFUL: Orchestrates pure computations and performs IO"""
    def action():
        # Call pure functions
        result1 = double(5).get()
        result2 = add(result1, 3).get()
        # Call effectful function
        printResult("Result", result2).run()
    return IO(action)

if __name__ == "__main__":
    compute_and_print().run()

