from typing import TypeVar, Generic, Callable
from dataclasses import dataclass

# Effect markers
class IO:
    """Marker for IO effects"""
    pass

class FS:
    """Marker for filesystem effects"""
    pass

# Generic effect type
T = TypeVar('T')

@dataclass
class Effect(Generic[T]):
    """Wrapper for effectful computations"""
    run: Callable[[], T]
    effects: tuple = ()

# PURE function - no effects
def computeSum(a: int, b: int) -> int:
    return a + b

# IO effect function
def printSum(a: int, b: int) -> Effect[None]:
    def _run():
        result = computeSum(a, b)
        print(f"Sum: {result}")
    return Effect(run=_run, effects=(IO,))

# IO + FS effects function
def logToFile(filename: str, message: str) -> Effect[None]:
    def _run():
        with open(filename, 'w') as f:
            f.write(message)
    return Effect(run=_run, effects=(IO, FS))

def main():
    # Call pure function
    result = computeSum(10, 20)

    # Call IO function
    printSum(10, 20).run()

    # Call IO+FS function
    logToFile("output.txt", "Sum was 30").run()

    # Print done
    print("Done")

if __name__ == "__main__":
    main()

