from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Generic, TypeVar, Union

T = TypeVar("T")
U = TypeVar("U")


@dataclass(frozen=True)
class Ok(Generic[T]):
    value: T


@dataclass(frozen=True)
class Err:
    message: str


Result = Union[Ok[T], Err]


def parse_int(s: str) -> Result[int]:
    try:
        return Ok(int(s))
    except (ValueError, TypeError):
        return Err("Invalid integer")


def divide_safe(a: int, b: int) -> Result[int]:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)


def and_then(res: Result[T], f: Callable[[T], Result[U]]) -> Result[U]:
    if isinstance(res, Ok):
        return f(res.value)
    return res  # type: ignore[return-value]


def print_result(res: Result[int]) -> None:
    if isinstance(res, Ok):
        print(f"Result: {res.value}")
    else:
        print(f"Error: {res.message}")


def main() -> None:
    res1 = and_then(parse_int("10"), lambda n: divide_safe(n, 2))
    print_result(res1)

    res2 = and_then(parse_int("10"), lambda n: divide_safe(n, 0))
    print_result(res2)

    res3 = parse_int("abc")
    print_result(res3)


if __name__ == "__main__":
    main()

