import argparse
import re
import sys
from collections import Counter
from pathlib import Path
from typing import Iterable, List


WORD_RE = re.compile(r"\b\w+\b", re.UNICODE)


def parse_args(argv: Iterable[str] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Count word frequencies in a text file and show the top N words."
    )
    parser.add_argument(
        "path",
        nargs="?",
        default="-",
        help="Path to the input text file (use '-' or omit to read from stdin).",
    )
    parser.add_argument(
        "-n",
        "--top",
        type=int,
        default=10,
        help="Number of top words to display (default: 10).",
    )
    parser.add_argument(
        "-i",
        "--ignore-case",
        action="store_true",
        help="Perform case-insensitive counting.",
    )
    return parser.parse_args(list(argv) if argv is not None else None)


def read_text(path_str: str) -> str:
    if path_str == "-" or path_str == "":
        return sys.stdin.read()
    path = Path(path_str)
    if not path.exists():
        raise FileNotFoundError(f"File not found: {path}")
    if not path.is_file():
        raise IsADirectoryError(f"Not a file: {path}")
    with path.open("r", encoding="utf-8") as fh:
        return fh.read()


def tokenize(text: str, ignore_case: bool = True) -> List[str]:
    if ignore_case:
        text = text.lower()
    return WORD_RE.findall(text)


def count_words(tokens: Iterable[str]) -> Counter:
    return Counter(tokens)


def format_top(counter: Counter, top_n: int) -> str:
    most_common = counter.most_common(top_n)
    lines = [f"{word}\t{count}" for word, count in most_common]
    return "\n".join(lines)


def main(argv: Iterable[str] = None) -> int:
    args = parse_args(argv)
    try:
        text = read_text(args.path)
    except FileNotFoundError as exc:
        print(f"Error: {exc}", file=sys.stderr)
