from typing import Union

@dataclass
class Leaf:
    value: int

@dataclass
class Node:
    left: 'Tree'
    value: int
    right: 'Tree'

Tree = Union[Leaf, Node]

def tree_sum(tree: Tree) -> int:
    match tree:
        case Leaf(v):
            return v
        case Node(l, v, r):
            return tree_sum(l) + v + tree_sum(r)

def find_max(tree: Tree) -> int:
    match tree:
        case Leaf(v):
            return v
        case Node(l, v, r):
            left_max = find_max(l)
            right_max = find_max(r)
            return max(left_max, v, right_max)

