type State =
  | Green(int)
  | Yellow(int)
  | Red(int)

type Event =
  | Tick
  | Reset

func transition(state: State, event: Event) -> State {
  match (state, event) {
    (Green(timer), Tick) =>
      if timer > 0 then Green(timer - 1) else Yellow(3),
    (Yellow(timer), Tick) =>
      if timer > 0 then Yellow(timer - 1) else Red(10),
    (Red(timer), Tick) =>
      if timer > 0 then Red(timer - 1) else Green(20),
    (Green(_), Reset) => Green(20),
    (Yellow(_), Reset) => Green(20),
    (Red(_), Reset) => Green(20)
  }
}

func showState(state: State) -> string {
  match state {
    Green(n) => "GREEN (" ++ show(n) ++ "sec)",
    Yellow(n) => "YELLOW (" ++ show(n) ++ "sec)",
    Red(n) => "RED (" ++ show(n) ++ "sec)"
  }
}

func doTicks(state: State, n: int) -> State ! {IO} {
  if n <= 0 then state else {
    let newState = transition(state, Tick);
    print(showState(newState));
    doTicks(newState, n - 1)
  }
}

