class Reset:
    pass

def transition(state: Green | Yellow | Red, event: Tick | Reset) -> Green | Yellow | Red:
    """
    Transitions the traffic light state based on an event.
    """
    match event:
        case Tick():
            match state:
                case Green(timer):
                    return Green(timer - 1) if timer > 0 else Yellow(3)
                case Yellow(timer):
                    return Yellow(timer - 1) if timer > 0 else Red(10)
                case Red(timer):
                    return Red(timer - 1) if timer > 0 else Green(20)
        case Reset():
            return Green(20)

def show_state(state: Green | Yellow | Red) -> str:
    """
    Returns a string representation of the current traffic light state.
    """
    match state:
        case Green(timer):
            return f"GREEN ({timer}sec)"
        case Yellow(timer):
            return f"YELLOW ({timer}sec)"
        case Red(timer):
            return f"RED ({timer}sec)"

def main() -> None:
    """
    Simulates the traffic light behavior.
    """
    current_state: Green | Yellow | Red = Green(20)

    # Apply 25 Tick events
    for _ in range(25):
        current_state = transition(current_state, Tick())
        print(show_state(current_state))

    # Apply 1 Reset event
    current_state = transition(current_state, Reset())
    print(show_state(current_state))

    # Apply 5 more Tick events
    for _ in range(5):
        current_state = transition(current_state, Tick())
        print(show_state(current_state))

