export func foldTree(fn, acc: int, tree: Tree) -> int {
  match tree {
    Leaf(v) => fn(acc)(v),
    Node(left, v, right) => {
      let accLeft = foldTree(fn, acc, left);
      let accV = fn(accLeft)(v);
      foldTree(fn, accV, right)
    }
  }
}

func concat(xs: List[int], ys: List[int]) -> List[int] {
  match xs {
    [] => ys,
    ::(h, t) => h :: concat(t, ys)
  }
}

export func treeToList(tree: Tree) -> List[int] {
  match tree {
    Leaf(v) => [v],
    Node(left, v, right) => concat(concat(treeToList(left), [v]), treeToList(right))
  }
}

export func treeDepth(tree: Tree) -> int {
  match tree {
    Leaf(_) => 1,
    Node(left, _, right) => {
      let leftDepth = treeDepth(left);
      let rightDepth = treeDepth(right);
      1 + (if leftDepth > rightDepth then leftDepth else rightDepth)
    }
  }
