from dataclasses import dataclass
from typing import Callable, Union, List

@dataclass
class Leaf:
    value: int

@dataclass
class Node:
    left: 'Tree'
    value: int
    right: 'Tree'

Tree = Union[Leaf, Node]

def map_tree(fn: Callable[[int], int], tree: Tree) -> Tree:
    """
    Recursively applies a function to all values in the tree,
    returning a new tree with transformed values.
    """
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    else:  # isinstance(tree, Node)
        return Node(
            map_tree(fn, tree.left),
            fn(tree.value),
            map_tree(fn, tree.right)
        )

def fold_tree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    """
    Performs an in-order fold over tree values, combining all values
    using the given function and an initial accumulator.
    """
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    else:  # isinstance(tree, Node)
        # Fold left subtree
        acc_left = fold_tree(fn, acc, tree.left)
        # Combine with current node's value
        acc_val = fn(acc_left, tree.value)
        # Fold right subtree
        return fold_tree(fn, acc_val, tree.right)

def tree_to_list(tree: Tree) -> List[int]:
    """
    Performs an in-order traversal of the tree, returning a list of its values.
    Does not filter out dummy '0' values; filtering is handled by the caller.
    """
    if isinstance(tree, Leaf):
        return [tree.value]
    else:  # isinstance(tree, Node)
        return tree_to_list(tree.left) + [tree.value] + tree_to_list(tree.right)

def tree_depth(tree: Tree) -> int:
    """
    Calculates the maximum depth of the tree.
    A Leaf node has a depth of 1.
    """
    if isinstance(tree, Leaf):
        return 1
    else:  # isinstance(tree, Node)
        return 1 + max(tree_depth(tree.left), tree_depth(tree.right))

def main() -> None:
    # Build the example tree as specified
    # The Leaf(0) nodes are dummy placeholders for missing children in the ADT
    # and are filtered out when displaying the list of values.
    # The Node(Leaf(1), 3, Leaf(0)) represents a node with value 3, left child 1, no right child.
    example_tree: Tree = Node(
        Node(Leaf(1), 3, Leaf(0)),  # left subtree for 5
        5,
        Node(Leaf(7), 8, Leaf(9))   # right subtree for 5
    )

    # 1. Original values
    # tree_to_list includes dummy 0s, so filter them out for printing.
    original_raw_list = tree_to_list(example_tree)
    original_filtered = [val for val in original_raw_list if val != 0]
    print(f"Original: {original_filtered}")

    # 2. Doubled values
    doubled_tree = map_tree(lambda x: x * 2, example_tree)
    doubled_raw_list = tree_to_list(doubled_tree)
    doubled_filtered = [val for val in doubled_raw_list if val != 0]
    print(f"Doubled: {doubled_filtered}")

    # 3. Sum of all values (including dummy 0s, which don't affect sum)
    tree_sum = fold_tree(lambda a, b: a + b, 0, example_tree)
    print(f"Sum: {tree_sum}")

    # 4. Tree depth
    depth = tree_depth(example_tree)
    print(f"Depth: {depth}")

if __name__ == "__main__":
    main()

